  ix <- seq.int(1L,nchar(hex),by=2L)
  bytes <- as.raw(strtoi(substring(hex,ix,ix+1L),base=16L))
  archive <- tempfile('MCPB_fixed_payload_',fileext='.zip')
  on.exit(unlink(archive),add=TRUE)
  writeBin(bytes,archive)
  stopifnot(identical(unname(tools::md5sum(archive)),'91ac9a9eb3b14397878c3f7eef9cc066'))
  support <- file.path(driver_root,'JOEF_MCPB_support_R03_91ac9a9eb3')
  dir.create(support,recursive=TRUE,showWarnings=FALSE)
  utils::unzip(archive,exdir=support,unzip='internal')
  manifest <- utils::read.csv(file.path(support,'EMBEDDED_INPUTS_MD5.csv'),stringsAsFactors=FALSE)
  files <- file.path(support,manifest$file)
  stopifnot(all(file.exists(files)),all(unname(tools::md5sum(files))==manifest$md5))
  core <- file.path(support,'JOEF_MCPB_v0_2_FULL.R')
  stopifnot(identical(unname(tools::md5sum(core)),'7198511bb116a1cd872cc25dc94122cc'))
  mode <- tolower(Sys.getenv('JOEF_MCPB_MODE','full'))
  if (!(mode %in% c('full','check'))) stop('JOEF_MCPB_MODE must be full or check.')
  autorun <- !(tolower(Sys.getenv('JOEF_MCPB_NO_AUTO','false')) %in% c('1','true','yes'))
  previous_auto <- Sys.getenv('JOEF_MCPB_NO_AUTO',unset=NA_character_)
  on.exit(if (is.na(previous_auto)) Sys.unsetenv('JOEF_MCPB_NO_AUTO') else
    Sys.setenv(JOEF_MCPB_NO_AUTO=previous_auto),add=TRUE)
  if (!nzchar(Sys.getenv('JOEF_MCPB_OUTDIR','')))
    Sys.setenv(JOEF_MCPB_OUTDIR=file.path(driver_root,'JOEF_MCPB_RESULTS_2024'))
  out <- normalizePath(Sys.getenv('JOEF_MCPB_OUTDIR'),winslash='/',mustWork=FALSE)
  status_file <- file.path(out,'RUN_STATUS.txt')
  completed <- file.exists(status_file) && identical(readLines(status_file,n=1L,warn=FALSE),'COMPLETE')
  run_models <- autorun && mode=='full' && !completed
  if (run_models && dir.exists(out) && length(list.files(out,all.files=FALSE)))
    stop('Use a new empty JOEF_MCPB_OUTDIR for model fitting. Partial runs are preserved; no silent overwrite.')
  if (autorun) {
    dir.create(out,recursive=TRUE,showWarnings=FALSE)
    driver_ok <- FALSE
    on.exit(writeLines(if(driver_ok) 'COMPLETE' else 'INCOMPLETE',
      file.path(out,'DRIVER_STATUS.txt')),add=TRUE)
    log <- file.path(out,'DRIVER_CONSOLE_LOG.txt')
    old_sinks <- sink.number(); sink(log,append=TRUE,split=TRUE)
    on.exit({ while(sink.number()>old_sinks) sink() },add=TRUE)
    cat(format(Sys.time(),'%Y-%m-%d %H:%M:%S %Z'),'| MCPB runner; mode=',mode,
      '; models=',run_models,'; fixed inputs verified\n',sep='')
  }
  Sys.setenv(JOEF_MCPB_NO_AUTO=if (run_models) 'false' else 'true')
  if (run_models) {
    old_rng <- RNGkind(); RNGkind('Mersenne-Twister','Inversion','Rejection')
    on.exit(do.call(RNGkind,as.list(old_rng)),add=TRUE)
    cat('Starting the fixed 120-case experiment with 4,999 bootstrap draws.\n')
  }
  tryCatch({
    source(core,encoding='UTF-8',local=.GlobalEnv)
    assign('MCPB_SUPPORT_DIR',support,envir=.GlobalEnv)
    if (autorun && mode=='check') {
      tests <- mc_selftests(list())
      utils::write.csv(tests,file.path(out,'DRIVER_SELFTESTS.csv'),row.names=FALSE)
      print(tests); cat('CHECK COMPLETE: 14 functional checks. No empirical run performed.\n')
      driver_ok <- TRUE
    } else if (autorun) {
      if (!file.exists(status_file) ||
          !identical(readLines(status_file,n=1L,warn=FALSE),'COMPLETE'))
        stop('The numerical run did not reach COMPLETE; inspect its logs.')
      qa <- file.path(out,'replication_qa')
      dir.create(qa,recursive=TRUE,showWarnings=FALSE)
      utils::write.csv(data.frame(component='frozen_numerical_core',
        file=basename(core),md5=unname(tools::md5sum(core))),
        file.path(qa,'DRIVER_COMPONENTS.csv'),row.names=FALSE)
      if (!is.na(driver_file) && file.exists(driver_file))
        file.copy(driver_file,file.path(qa,'SOURCE_COMPLETE_DRIVER.R'),overwrite=TRUE)
      cat('NUMERICAL RUN COMPLETE. Results folder: ',out,'\n',sep='')
      cat('For publication tables and figures use build_outputs.py as documented.\n')
      cat('Execution success does not establish general superiority or referee completion.\n')
      driver_ok <- TRUE
    } else cat('Functions and fixed inputs loaded. No empirical run started.\nSupport: ',support,'\n',sep='')
  },error=function(e) {
    if (autorun && dir.exists(out))
      writeLines(c(format(Sys.time(),'%Y-%m-%d %H:%M:%S %Z'),conditionMessage(e)),
        file.path(out,'DRIVER_LAST_ERROR.txt'))
    stop(conditionMessage(e),call.=FALSE)
  })
  invisible(support)
})()
